// 无明确目录的新头/新收据必须拒；可选NPC意图不能脱离真实补任与原政治事业目录。
#include "political_subordinate_appointment_profile.hpp"
#include "resident/domains/politics/succession/political_succession_profile.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
namespace hanmo::resident {
bool is_political_subordinate_appointment_fact_kind(const StableId& k){return k=="political_subordinate_appointment_offered"||k=="political_subordinate_appointment_accepted"||k=="political_subordinate_appointment_declined"||k=="political_subordinate_appointment_withdrawn"||k=="political_subordinate_appointment_arrived";}
Outcome<Integer> political_subordinate_appointment_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){Integer version=0,intents=0;for(const auto& m:modules){if(m.first==political_subordinate_appointment_module){if(m.second!="1"||version++)return {false,0,common_failure("PoliticalSubordinateAppointmentModuleMismatch").error};}if(m.first==political_subordinate_appointment_intents_module&&(m.second!="1"||intents++))return {false,0,common_failure("PoliticalSubordinateIntentModuleMismatch").error};}if(intents&&!version)return {false,0,common_failure("PoliticalSubordinateIntentProfileRequired").error};if(!version)return {true,0,{}};auto old=political_succession_selected_version(modules);if(!old.ok)return old;if(old.value!=1)return {false,0,common_failure("PoliticalSubordinateOriginalProfileRequired").error};return {true,1,{}};}
Outcome<std::optional<PoliticalSubordinateAppointmentCatalog>> decode_political_subordinate_appointment_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* d=scenario.find("dynamic_world");const auto* group=d?d->find(political_subordinate_appointment_module):nullptr;if(!group){if(d&&d->find(political_subordinate_appointment_intents_module))return {false,{},common_failure("PoliticalSubordinateIntentProfileRequired").error};return {true,std::nullopt,{}};}auto old=decode_political_succession_profile(scenario,caps);if(!old.ok)return {false,{},old.error};if(!old.value)return {false,{},common_failure("PoliticalSubordinateOriginalProfileRequired").error};if(std::find(caps.begin(),caps.end(),"political_subordinate_appointments_v1")==caps.end())return {false,{},common_failure("PoliticalSubordinateAppointmentCapabilityRequired").error};auto out=decode_political_subordinate_appointment_catalog(*group);if(!out.ok)return {false,{},out.error};if(out.value.policies.empty()||out.value.policies.size()>4096)return {false,{},common_failure("InvalidPoliticalSubordinateAppointmentCatalog").error};return {true,std::move(out.value),{}};}
Outcome<std::optional<PoliticalSubordinateAppointmentIntentCatalog>> decode_political_subordinate_intent_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){const auto* d=scenario.find("dynamic_world");const auto* group=d?d->find(political_subordinate_appointment_intents_module):nullptr;if(!group)return {true,std::nullopt,{}};auto pair=decode_political_subordinate_appointment_profile(scenario,caps);if(!pair.ok)return {false,{},pair.error};if(!pair.value||!d->find("director")||std::find(caps.begin(),caps.end(),"political_subordinate_appointment_intents_v1")==caps.end())return {false,{},common_failure("PoliticalSubordinateIntentProfileRequired").error};auto out=decode_political_subordinate_appointment_intents(*group);return out.ok?Outcome<std::optional<PoliticalSubordinateAppointmentIntentCatalog>>{true,std::move(out.value),{}}:Outcome<std::optional<PoliticalSubordinateAppointmentIntentCatalog>>{false,{},out.error};}
Status validate_political_subordinate_appointment_layout(const CommonStore& c,const std::vector<std::pair<StableId,StableId>>& modules,const PoliticalSubordinateAppointmentState* state){auto v=political_subordinate_appointment_selected_version(modules);if(!v.ok)return {false,{},v.error};if(bool(state)!=(v.value!=0)||(state&&state->version!=v.value))return common_failure("PoliticalSubordinateAppointmentProfileMismatch");if(state)return validate_political_subordinate_appointment_layout(*state);for(const auto& row:c.state().facts.rows())if(is_political_subordinate_appointment_fact_kind(row.second.kind)||row.second.domain==political_subordinate_appointment_module)return common_failure("PoliticalSubordinateAppointmentProfileRequired",row.first);for(const auto& row:c.state().results.rows())if(row.second&&is_political_subordinate_appointment_command(row.second->kind))return common_failure("PoliticalSubordinateAppointmentProfileRequired",row.first);for(const auto& h:c.state().history)if(is_political_subordinate_appointment_command(h.kind))return common_failure("PoliticalSubordinateAppointmentProfileRequired",h.result_id);return common_success();}
Status validate_political_subordinate_appointment_fact_header(const CommonStore& c,const PoliticalSubordinateAppointmentState& state,const FactRecord& h){bool found=false;if(h.kind=="political_subordinate_appointment_offered"){const auto* r=state.offers.find(h.id);found=r&&r->id==h.id;}else if(h.kind=="political_subordinate_appointment_accepted"||h.kind=="political_subordinate_appointment_declined"){const auto* r=state.answers.find(h.id);found=r&&r->id==h.id&&r->accepted==(h.kind=="political_subordinate_appointment_accepted");}else if(h.kind=="political_subordinate_appointment_withdrawn"){const auto* r=state.withdrawals.find(h.id);found=r&&r->id==h.id;}else if(h.kind=="political_subordinate_appointment_arrived"){const auto* r=state.arrivals.find(h.id);found=r&&r->id==h.id;}return state.version==1&&found&&h.domain==political_subordinate_appointment_module&&political_subordinate_appointment_fact_sequence(c,h.id)?common_success():common_failure("PoliticalSubordinateAppointmentFactMismatch",h.id);}
// 精确新源前缀不可被原political_appoint或其它旧kind消费。
bool political_subordinate_appointment_effect_uses_sources(const PoliticsEffects& e){for(const auto* ids:{&e.fact_ids,&e.receipt_ids})for(const auto& id:*ids)if(id.rfind("political_subordinate_",0)==0)return true;return false;}
bool valid_political_subordinate_appointment_effect(const StableId& kind,const PoliticsEffects& e){if(!is_political_subordinate_appointment_command(kind)||!e.appointment_id.empty()||e.fact_ids!=e.receipt_ids)return false;const bool arrival=kind==political_subordinate_arrive_command;if(e.fact_ids.size()!=(arrival?2u:1u))return false;StableId prefix=kind==political_subordinate_offer_command?"political_subordinate_offer":kind==political_subordinate_answer_command?"political_subordinate_answer":kind==political_subordinate_withdraw_command?"political_subordinate_withdrawal":"political_subordinate_arrival";auto n=organization_instance_sequence(e.fact_ids.front(),prefix);if(!n)return false;if(!arrival)return true;if(*n==std::numeric_limits<Integer>::max())return false;auto office=organization_instance_sequence(e.fact_ids.back(),"organization");return office&&*office==*n+1;}
}
